WORD_BOUNDARY = (
    f"(?:(?<![{SOURCE_WORD}])(?=[{SOURCE_WORD}])"
    f"|(?<=[{SOURCE_WORD}])(?![{SOURCE_WORD}]))"
)
WORD_NONBOUNDARY = (
    f"(?:(?<=[{SOURCE_WORD}])(?=[{SOURCE_WORD}])"
    f"|(?<![{SOURCE_WORD}])(?![{SOURCE_WORD}]))"
)


def expand_portable(source: str) -> str:
    """\\s \\S \\w \\W \\b \\B -> explicit source-semantics constructs.

    Mirrors the TS walk exactly: inside a class \\s/\\w become bare
    fragments and \\b stays (backspace); \\S/\\W/\\B inside a class
    raise; outside, \\b/\\B become the lookaround pair over the source
    word class.
    """
    out: list[str] = []
    in_class = False
    i = 0
    while i < len(source):
        ch = source[i]
        if ch == "\\" and i + 1 < len(source):
            nxt = source[i + 1]
            if nxt == "s":
                out.append(SOURCE_WHITESPACE if in_class else f"[{SOURCE_WHITESPACE}]")
                i += 2
                continue
            if nxt == "w":
                out.append(SOURCE_WORD if in_class else f"[{SOURCE_WORD}]")
                i += 2
                continue
            if nxt in ("S", "W"):
                if in_class:
                    raise ValueError(
                        f"\\{nxt} inside a character class cannot be expanded portably"
                    )
                frag = SOURCE_WHITESPACE if nxt == "S" else SOURCE_WORD
                out.append(f"[^{frag}]")
                i += 2
                continue
            if nxt == "b" and not in_class:
                out.append(WORD_BOUNDARY)
                i += 2
                continue
            if nxt == "B":
                if in_class:
                    raise ValueError(
                        "\\B inside a character class cannot be expanded portably"
                    )
                out.append(WORD_NONBOUNDARY)
                i += 2
                continue
            out.append(ch + nxt)
            i += 2
            continue
        if ch == "[" and not in_class:
            in_class = True
        elif ch == "]" and in_class:
            in_class = False
        out.append(ch)
        i += 1
    return "".join(out)


# Former name, kept for callers.
expand_whitespace = expand_portable


def expand_pattern(source: str, defs: dict[str, str] | None = None) -> str:
    """{{name}} splicing to a fixpoint; must match the TS expansion."""
    table = defs or {}
    out = source
    for _ in range(11):
        def _sub(match: re.Match[str]) -> str:
            name = match.group(1)
            if name not in table:
                raise KeyError(f"grammar def {{{{{name}}}}} is not defined")
            return table[name]

        nxt = _DEF_REF.sub(_sub, out)
        if nxt == out:
            return out
        out = nxt
    raise ValueError("grammar defs reference each other in a cycle")


def validate_pattern(source: str) -> list[str]:
    violations: list[str] = []
    if "(?P" in source:
        violations.append("(?P named-group syntax: author JS-style (?<name>...)")
    if re.search(r"\\[pP]\{", source):
        violations.append("\\p{...} classes: unsupported in re")
    for match in re.finditer(r"\(\?([a-zA-Z-]+)[:)]", source):
        violations.append(f"inline flags (?{match.group(1)}...: banned")
    if re.search(r"(?:^|[^\\])\(\?\(", source):
        # \(? followed by a group is not a conditional; require the opening
        # paren to be unescaped, mirroring the TS validator.
        violations.append("conditional groups: not portable")
    if re.search(r"\\u\{", source):
        violations.append("braced \\u{...} escape: JS-only; use \\uXXXX or the literal")
    return violations


def compile_entry(entry: dict, defs: dict[str, str] | None = None) -> re.Pattern[str]:
    expanded = expand_portable(expand_pattern(entry["pattern"], defs))
    source = _NAMED_GROUP.sub(r"(?P<\1>", expanded)
    flags = re.ASCII
    for ch in entry.get("flags", ""):
        flags |= _FLAG_BITS[ch]
    return re.compile(source, flags)


def canonicalize(groups: dict, rules: dict) -> dict:
    out = dict(groups)
    for name in rules.get("lowercase", []):
        if name in out and out[name] is not None:
            out[name] = out[name].lower()
    for name, chars in rules.get("strip", {}).items():
        if name in out and out[name] is not None:
            out[name] = "".join(ch for ch in out[name] if ch not in chars)
    for name, mapping in rules.get("map", {}).items():
        if name in out and out[name] in mapping:
            out[name] = mapping[out[name]]
    return out


def run_vectors(table: dict) -> list[str]:
    failures: list[str] = []
    defs = table.get("defs") or {}
    for entry in table.get("entries", []):
        eid = entry.get("id", "?")
        try:
            expanded = expand_pattern(entry["pattern"], defs)
        except (KeyError, ValueError) as error:
            failures.append(f"{eid}: {error}")
            continue
        for violation in validate_pattern(expanded):
            failures.append(f"{eid}: {violation}")
        if not re.fullmatch(r"[ims]*", entry.get("flags", "")):
            failures.append(f'{eid}: flags must be a subset of "ims"')
        try:
            pattern = compile_entry(entry, defs)
        except re.error as error:
            failures.append(f"{eid}: does not compile in Python: {error}")
            continue
        for vector in entry.get("vectors", []):
            match = pattern.search(vector["input"])
            expected = vector["groups"]
            if expected is None:
                if match:
                    failures.append(
                        f'{eid}: "{vector["input"]}" expected no match, got "{match.group(0)}"'
                    )
                continue
            if not match:
                failures.append(f'{eid}: "{vector["input"]}" expected a match, got none')
                continue
            got = match.groupdict()
            for name, value in expected.items():
                if got.get(name) != value:
                    failures.append(
                        f'{eid}: "{vector["input"]}" group {name}: expected "{value}", got "{got.get(name)}"'
                    )
            if vector.get("canonical"):
                canon = canonicalize(got, entry.get("canonical", {}))
                for name, value in vector["canonical"].items():
                    if canon.get(name) != value:
                        failures.append(
                            f'{eid}: "{vector["input"]}" canonical {name}: expected "{value}", got "{canon.get(name)}"'
                        )
    return failures


def check_dir(table_dir: Path) -> int:
    paths = sorted(table_dir.glob("*.json"))
    if not paths:
        print(f"no grammar tables under {table_dir}", file=sys.stderr)
        return 2
    failed = 0
    for path in paths:
        table = json.loads(path.read_text(encoding="utf-8"))
        if table.get("format") != GRAMMAR_TABLE_FORMAT:
            print(f"{path.name}: unexpected format {table.get('format')}")
            failed += 1
            continue
        failures = run_vectors(table)
        entries = len(table.get("entries", []))
        vectors = sum(len(e.get("vectors", [])) for e in table.get("entries", []))
        if failures:
            failed += 1
            print(f"{path.name}: FAIL ({entries} entries, {vectors} vectors)")
            for failure in failures:
                print(f"  {failure}")
        else:
            print(f"{path.name}: ok ({entries} entries, {vectors} vectors)")
    return 1 if failed else 0


def load_tables(dir: Path | None = None) -> dict[str, tuple[dict, dict]]:
    """{entry_id: (entry, defs)} across every grammar table in one directory.

    Resolution order: the explicit argument, then $BEAVER_GRAMMAR_TABLES,
    then the copies vendored under data/grammar-tables.
    """
    if dir is not None:
        table_dir = Path(dir)
    else:
        env = os.environ.get("BEAVER_GRAMMAR_TABLES")
        table_dir = Path(env) if env else VENDORED_TABLE_DIR
    paths = sorted(table_dir.glob("*.json"))
    if not paths:
        raise FileNotFoundError(f"no grammar tables under {table_dir}")
    tables: dict[str, tuple[dict, dict]] = {}
    for path in paths:
        table = json.loads(path.read_text(encoding="utf-8"))
        if table.get("format") != GRAMMAR_TABLE_FORMAT:
            raise ValueError(f"{path}: unexpected format {table.get('format')!r}")
        defs = table.get("defs") or {}
        for entry in table.get("entries", []):
            entry_id = entry["id"]
            if entry_id in tables:
                raise ValueError(f"{path}: duplicate grammar entry id {entry_id!r}")
            tables[entry_id] = (entry, defs)
    return tables


_DEFAULT_TABLES: dict[str, tuple[dict, dict]] | None = None


def compile_table_entry(
    entry_id: str, tables: dict[str, tuple[dict, dict]] | None = None
) -> re.Pattern[str]:
    """Compile one entry by id; the default tables are loaded once per process."""
    global _DEFAULT_TABLES
    if tables is None:
        if _DEFAULT_TABLES is None:
            _DEFAULT_TABLES = load_tables()
        tables = _DEFAULT_TABLES
    entry, defs = tables[entry_id]
    return compile_entry(entry, defs)


class _LazyTableEntry:
    """A table entry that compiles on first use and then acts as its pattern.

    Boundary expansion makes the compiled tables expensive (~1.8s cold for
    the 26 splitter entries), so modules that bind many of these at import
    must not pay that up front. Method and attribute access delegates to
    the compiled re.Pattern; the __class__ property keeps
    isinstance(x, re.Pattern) probes (tools/grammar_differential.py)
    truthful about what callers receive.
    """

    __slots__ = ("_entry_id", "_pattern")

    def __init__(self, entry_id: str) -> None:
        self._entry_id = entry_id
        self._pattern: re.Pattern[str] | None = None

    @property
    def __class__(self):  # noqa: D105 - deliberate re.Pattern impersonation
        return re.Pattern

    def __getattr__(self, name: str):
        if self._pattern is None:
            self._pattern = compile_table_entry(self._entry_id)
        return getattr(self._pattern, name)


def lazy_table_entry(entry_id: str) -> re.Pattern[str]:
    """A re.Pattern-shaped handle on one table entry, compiled at first use."""
    return _LazyTableEntry(entry_id)  # type: ignore[return-value]


def sync_warnings() -> list[str]:
    """Byte-compare the vendored tables against their authoring directory.

    The authoring directory is $BEAVER_GRAMMAR_TABLES when set, else the
    workspace's shared/grammar-tables when that checkout is present.
    Warnings, never failures: the fork is not always there, and the
    vendored copies are the runtime source of truth.
    """
    env = os.environ.get("BEAVER_GRAMMAR_TABLES")
    upstream = Path(env) if env else _FORK_TABLE_DIR
    if not upstream.is_dir() or upstream.resolve() == VENDORED_TABLE_DIR.resolve():
        return []
    names = sorted(
        {path.name for path in upstream.glob("*.json")}
        | {path.name for path in VENDORED_TABLE_DIR.glob("*.json")}
    )
    warnings: list[str] = []
    for name in names:
        vendored, authored = VENDORED_TABLE_DIR / name, upstream / name
        if not vendored.is_file():
            warnings.append(f"{name}: present in {upstream} but not vendored")
        elif not authored.is_file():
            warnings.append(f"{name}: vendored but absent from {upstream}")
        elif vendored.read_bytes() != authored.read_bytes():
            warnings.append(f"{name}: vendored copy differs byte-wise from {authored}")
    return warnings


if __name__ == "__main__":
    args = sys.argv[1:]
    if len(args) == 2 and args[0] == "--check":
        status = check_dir(Path(args[1]))
        # Drift between the vendored tables and their authoring home is a
        # FAILURE when both are visible: the one live drift this repo has
        # had (three entries vendored but never authored upstream) sailed
        # through because these were warnings. sync_warnings() is empty
        # when no authoring checkout is present, so standalone use of the
        # engine is unaffected.
        drift = sync_warnings()
        for warning in drift:
            print(f"error: grammar-table sync: {warning}", file=sys.stderr)
        raise SystemExit(status or (1 if drift else 0))
    print("usage: python -m legalpdf.grammar_tables --check <table-dir>", file=sys.stderr)
    raise SystemExit(2)
